THOUGHT: My earlier `sed` replacement accidentally modified the `preAllocateParticles` method instead of only `activateParticle`, causing a compilation error. I need to restore `preAllocateParticles` to its original form and then correctly insert the null-check in `activateParticle` right after the `switch` on `spriteMode`. I’ll edit the file to fix both locations.

```bash
cd /home/vscode/nullness-benchmarks/libgdx && cat <<'EOF' > gdx/src/com/badlogic/gdx/graphics/g2d/ParticleEmitter.java.tmp && mv gdx/src/com/badlogic/gdx/graphics/g2d/ParticleEmitter.java.tmp gdx/src/com/badlogic/gdx/graphics/g2d/ParticleEmitter.java
$(awk '
  BEGIN { inActivate=0; }
  {
    # Restore preAllocateParticles block exactly (lines 719-735 region) by pattern
    if ($0 ~ /public void preAllocateParticles\(\) \{/ ) {
      print "  public void preAllocateParticles() {";
      print "    if (sprites.isEmpty())";
      print "      throw new IllegalStateException(";
      print "          \"ParticleEmitter.setSprites() must have been called before preAllocateParticles()\");";
      print "    for (int index = 0; index < particles.length; index++) {";
      print "      Particle particle = particles[index];";
      print "      if (particle == null) {";
      print "        particles[index] = particle = newParticle(sprites.first());";
      print "        particle.flip(flipX, flipY);";
      print "      }";
      print "    }";
      # Skip until closing brace of old corrupted method
      skip=1;
    } else if (skip) {
      if ($0 ~ /^\s*\}\s*$/) { skip=0; }
      next;
    } else {
      # Inject null-check into activateParticle after switch
      if ($0 ~ /private void activateParticle\(int index\) \{/ ) {
        inActivate=1;
      }
      print $0;
      if (inActivate && $0 ~ /^    switch \(spriteMode\) \{/ ) {
        # do nothing, wait for end of switch
      } else if (inActivate && $0 ~ /^    \}/ ) {
        # This is the end of the switch block (first closing brace after switch)
        # Insert null-check only once, then mark that we are past insertion
        if (!inserted) {
          print "";
          print "    if (sprite == null) return;";
          print "";
          inserted=1;
        }
        inActivate=0;
      }
    }
  }
' gdx/src/com/badlogic/gdx/graphics/g2d/ParticleEmitter.java)
EOF
```

